import React, { useState, useEffect } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import axios from 'axios';

const Settings = () => {
    const navigate = useNavigate();
    const location = useLocation();
    const [user, setUser] = useState(null);
    const [showModal, setShowModal] = useState(false);
    const [modalType, setModalType] = useState('');
    const [formData, setFormData] = useState({});
    const [selectedFile, setSelectedFile] = useState(null);

    // Load user from localStorage FIRST, then refresh from API
    useEffect(() => {
        const storedUser = localStorage.getItem('user');
        if (storedUser) setUser(JSON.parse(storedUser));

        const fetchUser = async () => {
            try {
                const token = localStorage.getItem('token');
                const res = await axios.get('http://localhost:5000/api/auth/me', {
                    headers: { Authorization: `Bearer ${token}` }
                });
                setUser(res.data.user);
                localStorage.setItem('user', JSON.stringify(res.data.user));
            } catch (err) {
                console.error("Error fetching user", err);
            }
        };
        fetchUser();
    }, []);

    const handleLogout = () => {
        localStorage.removeItem('token');
        localStorage.removeItem('user');
        navigate('/login');
    };

    const isActive = (path) => location.pathname === path;

    const openModal = (type) => {
        setModalType(type);
        setFormData({});
        setSelectedFile(null);
        setShowModal(true);
    };

    const closeModal = () => {
        setShowModal(false);
        setModalType('');
        setFormData({});
        setSelectedFile(null);
    };

    const handleFileChange = (e) => setSelectedFile(e.target.files[0]);
    const handleChange = (e) => setFormData({ ...formData, [e.target.name]: e.target.value });

    // ✅ REAL-TIME UPDATE FUNCTION
    const handleSubmit = async (e) => {
        e.preventDefault();
        try {
            const token = localStorage.getItem('token');

            // 1. PICTURE
            if (modalType === 'picture' && selectedFile) {
                const reader = new FileReader();
                reader.readAsDataURL(selectedFile);
                reader.onload = async () => {
                    try {
                        const res = await axios.put('http://localhost:5000/api/auth/update-profile-image', 
                            { profileImage: reader.result },
                            { headers: { Authorization: `Bearer ${token}` } }
                        );
                        setUser(res.data.user);
                        localStorage.setItem('user', JSON.stringify(res.data.user));
                        alert("✅ Picture updated!");
                        closeModal();
                    } catch (err) { alert("❌ Failed to upload picture."); }
                };
            } 
            // 2. DELETE PICTURE
            else if (modalType === 'deletePicture') {
                try {
                    const res = await axios.put('http://localhost:5000/api/auth/update-profile-image', 
                        { profileImage: null },
                        { headers: { Authorization: `Bearer ${token}` } }
                    );
                    setUser(res.data.user);
                    localStorage.setItem('user', JSON.stringify(res.data.user));
                    alert("✅ Picture deleted!");
                    closeModal();
                } catch (err) { alert("❌ Failed to delete picture."); }
            }
            // 3. PASSWORD
            else if (modalType === 'password') {
                if (formData.newPassword !== formData.confirmPassword) { alert("❌ Passwords do not match!"); return; }
                if (formData.newPassword.length < 8) { alert("❌ Password must be at least 8 characters!"); return; }

                try {
                    await axios.put('http://localhost:5000/api/auth/update', 
                        { password: formData.newPassword },
                        { headers: { Authorization: `Bearer ${token}` } }
                    );
                    alert("✅ Password changed! Please login again.");
                    localStorage.removeItem('token'); localStorage.removeItem('user');
                    navigate('/login');
                } catch (err) { alert("❌ Failed to change password."); }
            }
            // 4. NAME, EMAIL/PHONE, LANGUAGE
            else {
                let updateData = {};
                if (modalType === 'name') updateData = { firstName: formData.firstName, lastName: formData.lastName };
                else if (modalType === 'emailPhone') updateData = { email: formData.email, phone: formData.phone };
                else if (modalType === 'language') updateData = { language: formData.language };

                try {
                    const res = await axios.put('http://localhost:5000/api/auth/update', updateData, {
                        headers: { Authorization: `Bearer ${token}` }
                    });
                    setUser(res.data.user);
                    localStorage.setItem('user', JSON.stringify(res.data.user));
                    alert("✅ Changes saved!");
                    closeModal();
                } catch (err) { alert("❌ Failed to update."); }
            }
        } catch (err) { alert("❌ Failed to update."); }
    };

    return (
        <div className="settings-page">
            <nav className="settings-navbar">
                <div className="nav-logo">BeautyBook</div>
                <div className="nav-links-desktop">
                    <span className={`nav-item ${isActive('/services') ? 'active' : ''}`} onClick={() => navigate('/services')}>🌸 Beauty treatments</span>
                    <span className={`nav-item ${isActive('/appointments') ? 'active' : ''}`} onClick={() => navigate('/appointments')}>📅 Appointment</span>
                    <span className="nav-icon" onClick={() => navigate('/settings')} style={{cursor: 'pointer'}}>⚙️</span>
                </div>
            </nav>

            <div className="settings-content">
                <div className="decorative-icons">
                    <span className="icon-1">💄</span><span className="icon-2">🌸</span><span className="icon-3">💅</span>
                    <span className="icon-4">🧴</span><span className="icon-5">💋</span><span className="icon-6">🪞</span>
                </div>

                <div className="settings-card">
                    <div className="profile-section">
                        <div className="profile-avatar">
                            {user && user.profileImage ? (
                                <img src={user.profileImage} alt="Profile" className="profile-image" />
                            ) : (
                                <svg width="80" height="80" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                                    <circle cx="12" cy="12" r="12" fill="#fce4b8" />
                                    <circle cx="12" cy="9.5" r="4" fill="#f8c3a1" />
                                    <path d="M4 20c0-3.87 3.58-7 8-7s8 3.13 8 7" fill="#c4a35a" />
                                </svg>
                            )}
                        </div>
                        <h2 className="profile-name">{user?.firstName || user?.lastName ? `${user.firstName || ''} ${user.lastName || ''}` : 'your name'}</h2>
                    </div>

                    <div className="settings-buttons">
                        <button className="setting-btn" onClick={() => openModal('picture')}>change your picture</button>
                        <button className="setting-btn" onClick={() => openModal('deletePicture')}>Delete your picture</button>
                        <button className="setting-btn" onClick={() => openModal('name')}>change your name</button>
                        <button className="setting-btn" onClick={() => openModal('password')}>change your password</button>
                        <button className="setting-btn" onClick={() => openModal('language')}>change language</button>
                        <button className="setting-btn" onClick={() => openModal('emailPhone')}>change your email/phone</button>
                    </div>
                </div>
            </div>

            {showModal && (
                <div className="settings-modal-overlay" onClick={closeModal}>
                    <div className="settings-modal" onClick={(e) => e.stopPropagation()}>
                        <h3>Update Settings</h3>
                        <form onSubmit={handleSubmit}>
                            {modalType === 'picture' && (
                                <><label>Upload New Picture:</label><input type="file" accept="image/*" onChange={handleFileChange} required /></>
                            )}
                            {modalType === 'deletePicture' && <p style={{color: '#d32f2f'}}>Are you sure you want to delete your picture?</p>}
                            {modalType === 'name' && (
                                <><input type="text" name="firstName" placeholder="First Name" onChange={handleChange} required /><input type="text" name="lastName" placeholder="Last Name" onChange={handleChange} required /></>
                            )}
                            {modalType === 'password' && (
                                <><input type="password" name="newPassword" placeholder="New Password" onChange={handleChange} required /><input type="password" name="confirmPassword" placeholder="Confirm Password" onChange={handleChange} required /></>
                            )}
                            {modalType === 'emailPhone' && (
                                <><input type="email" name="email" placeholder="Email" onChange={handleChange} required /><input type="text" name="phone" placeholder="Phone" onChange={handleChange} required /></>
                            )}
                            {modalType === 'language' && (
                                <select name="language" onChange={handleChange} required>
                                    <option value="fr">French</option><option value="en">English</option><option value="ar">Arabic</option>
                                </select>
                            )}
                            <div className="modal-actions">
                                <button type="button" className="cancel-modal-btn" onClick={closeModal}>Cancel</button>
                                <button type="submit" className="confirm-booking-btn">Save</button>
                            </div>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );
};

export default Settings;
